function ReportsPanel({sales,jobs,products,cash}:any){const day=today();const todaySales=sales.filter((s:Row)=>s.createdAt?.slice(0,10)===day&&!s.voidedAt);const total=todaySales.reduce((n:number,s:Row)=>n+s.total,0);const pending=sales.filter((s:Row)=>(s.balance||0)>0&&!s.voidedAt).reduce((n:number,s:Row)=>n+s.balance,0);const download=()=>{const lines=[['Venta','Fecha','Estado','Total','Abonado','Saldo'],...sales.filter((s:Row)=>!s.voidedAt).map((s:Row)=>[s.number,s.createdAt?.slice(0,10),s.status,s.total,s.paid??s.received??0,s.balance??0])];const csv=lines.map(r=>r.map((v:any)=>`"${String(v??'').replaceAll('\"','\"\"')}"`).join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`reporte-ventas-${day}.csv`;a.click();URL.revokeObjectURL(url)};return <div className="reports-surface"><div className="report-actions"><button className="secondary" onClick={download}><Download size={17}/>Exportar para Excel</button><button className="primary" onClick={()=>window.print()}><Printer size={17}/>Imprimir reporte</button></div><div className="overview-grid"><section className="panel"><span className="eyebrow">REPORTE DE HOY</span><h2>{money(total)} vendidos</h2><p>{todaySales.length} ventas · {money(pending)} en saldos pendientes</p><div className="sale-payment-summary"><span>Trabajos atrasados <b>{jobs.filter((j:Row)=>j.due&&j.due<day&&j.status!=='Entregado').length}</b></span><span>Stock crítico <b>{products.filter((p:Row)=>p.stock<=p.minStock&&p.active!==false).length}</b></span></div></section><section className="panel"><span className="eyebrow">CAJA Y COBRANZA</span><h2>{cash.find((c:Row)=>c.date===day)?.status||'Caja sin cerrar'}</h2><p>Descuentos, abonos y medios de pago de la sucursal seleccionada.</p><div className="sale-payment-summary"><span>Tarjeta <b>{money(todaySales.reduce((n:number,s:Row)=>n+(s.payments||[]).filter((p:Row)=>p.method==='Tarjeta').reduce((v:number,p:Row)=>v+p.amount,0),0))}</b></span><span>Transferencia <b>{money(todaySales.reduce((n:number,s:Row)=>n+(s.payments||[]).filter((p:Row)=>p.method==='Transferencia').reduce((v:number,p:Row)=>v+p.amount,0),0))}</b></span></div></section></div></div>}
function AuditPanel({rows}:any){return <section className="panel"><div className="panel-heading"><div><span className="eyebrow">DESARROLLADOR</span><h2>Historial de cambios</h2><p>Registro de las últimas acciones realizadas en el CRM.</p></div></div>{rows.length?<Table><TableHeader><TableRow><TableHead>Fecha</TableHead><TableHead>Acción</TableHead><TableHead>Área</TableHead><TableHead>Registro</TableHead></TableRow></TableHeader><TableBody>{[...rows].reverse().slice(0,200).map((r:Row)=><TableRow key={r.id}><TableCell>{new Date(r.date).toLocaleString('es-CL')}</TableCell><TableCell>{r.action}</TableCell><TableCell>{r.kind}</TableCell><TableCell>{r.recordId?.slice(0,8)||'—'}</TableCell></TableRow>)}</TableBody></Table>:<Empty title="Sin movimientos" text="Las acciones registradas aparecerán aquí."/>}</section>}

function colIndex(ref:string){let n=0;for(const c of ref.replace(/\d/g,''))n=n*26+c.charCodeAt(0)-64;return n-1}
function normalizeHeader(v:any){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function mapPatients(rows:any[][]){if(rows.length<2)throw new Error('El archivo debe incluir encabezados y al menos un paciente.');const headers=rows[0].map(normalizeHeader);const read=(row:any[], names:string[])=>{const i=headers.findIndex(h=>names.some(n=>h===n||h.includes(n)));return i>=0?String(row[i]??'').trim():''};const patients=rows.slice(1).map(row=>({name:read(row,['nombre','paciente','nombrecompleto']),rut:read(row,['rut','cedula']),phone:read(row,['telefono','celular','fono','movil']),email:read(row,['correo','email']),birthDate:read(row,['fechanacimiento','nacimiento']),age:read(row,['edad'])})).filter(p=>p.name);if(!patients.length)throw new Error('No encontramos una columna Nombre con pacientes válidos.');return patients}
async function readSpreadsheet(file:File){if(file.name.toLowerCase().endsWith('.csv')){const text=await file.text();const sep=text.includes(';')?';':',';return text.split(/\r?\n/).filter(Boolean).map(line=>line.split(sep).map(v=>v.replace(/^"|"$/g,'').replaceAll('""','"')))}const bytes=new Uint8Array(await file.arrayBuffer());const view=new DataView(bytes.buffer);let pos=bytes.length-22;while(pos>=0&&view.getUint32(pos,true)!==0x06054b50)pos--;if(pos<0)throw new Error('No pudimos leer el archivo Excel. Prueba guardarlo como CSV UTF-8.');const central=view.getUint32(pos+16,true), count=view.getUint16(pos+10,true), dec=new TextDecoder();const files:any={};let at=central;for(let i=0;i<count;i++){if(view.getUint32(at,true)!==0x02014b50)break;const method=view.getUint16(at+10,true), size=view.getUint32(at+20,true), nameLen=view.getUint16(at+28,true), extra=view.getUint16(at+30,true), comment=view.getUint16(at+32,true), offset=view.getUint32(at+42,true), name=dec.decode(bytes.slice(at+46,at+46+nameLen));const localName=view.getUint16(offset+26,true),localExtra=view.getUint16(offset+28,true),data=bytes.slice(offset+30+localName+localExtra,offset+30+localName+localExtra+size);files[name]={method,data};at+=46+nameLen+extra+comment}const unpack=async(f:any)=>f.method===0?dec.decode(f.data):await new Response(new Blob([f.data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();const shared=files['xl/sharedStrings.xml']?Array.from(new DOMParser().parseFromString(await unpack(files['xl/sharedStrings.xml']),'application/xml').querySelectorAll('si')).map(n=>n.textContent||''):[];const sheet=Object.keys(files).find(k=>/^xl\/worksheets\/sheet\d+\.xml$/.test(k));if(!sheet)throw new Error('El Excel no contiene una hoja de datos.');const doc=new DOMParser().parseFromString(await unpack(files[sheet]),'application/xml');return Array.from(doc.querySelectorAll('row')).map(row=>{const cells:any[]=[];row.querySelectorAll('c').forEach(c=>{const i=colIndex(c.getAttribute('r')||'A1'),raw=c.querySelector('v')?.textContent||c.querySelector('t')?.textContent||'';cells[i]=c.getAttribute('t')==='s'?shared[Number(raw)]||'':raw});return cells})}

