 const record=rows.find((r:Row)=>r.date===today()); const cashSales=sales.filter((s:Row)=>!s.voidedAt&&s.createdAt?.slice(0,10)===today()).reduce((v:number,s:Row)=>v+(s.payments||[]).filter((p:Row)=>p.method==='Efectivo').reduce((n:number,p:Row)=>n+p.amount,0),0); const expected=Number(opening||0)+cashSales-Number(withdrawals||0);
